WITH wanted(name) AS (VALUES ('Porterhouse'),('Porterhouse (250g )'),('Parma (cafe)'),('Coke (cafe)'),('Latte - Small'),('Extra Shot'),('Oat milk'),('Margarita'),('Pint - Philter XPA'),('Coke Zero - Mixer'),('Beef Tartare'),('Apple Crumble'),('Kids Fish & Chippies'),('Can - Stone & Wood Pacific Ale (cafe)'))
SELECT s.item_name, string_agg(DISTINCT s.category_name,' | ' ORDER BY s.category_name) source_categories,min(s.trading_date) first_seen,max(s.trading_date) last_seen,count(*) observations FROM canonical_sale_item s JOIN wanted w ON w.name=s.item_name WHERE s.superseded_at IS NULL GROUP BY s.item_name ORDER BY s.item_name;
SELECT item_name,string_agg(DISTINCT category_name,' | ') categories,min(trading_date),max(trading_date),count(*) FROM canonical_sale_item WHERE superseded_at IS NULL AND category_name='MERCH' GROUP BY 1 ORDER BY 5 DESC LIMIT 3;
SELECT w.product_name_key,w.recipe_id,string_agg(DISTINCT w.unit_of_measurement_name,' | ') units,string_agg(DISTINCT w.supplier_name,' | ') suppliers,count(*) lines FROM canonical_wastage w WHERE superseded_at IS NULL AND product_name_key IN ('beef cheek denuded frozen order by kg','breast fillet butterflied pc 200g','bay of fires clothbound cheddar','bulla thickened cream','12 x 80g dill pickle chappy s potato chips','braised beef cheek') GROUP BY 1,2 ORDER BY 1;
SELECT sale_item_stock_description,recipe_id,recipe_name,recipe_folder_name,is_recipe_active,sale_item_recipe_id FROM canonical_sale_recipe_link WHERE superseded_at IS NULL AND sale_item_stock_description IN ('Porterhouse','Porterhouse (250g )','Margarita','Coke Zero - Mixer','Vegan Option','Pint - Philter XPA') ORDER BY sale_item_stock_description,recipe_id;
SELECT product_name_key,count(DISTINCT source_product_ref) ids FROM canonical_product_sales WHERE superseded_at IS NULL AND source_product_ref IS NOT NULL GROUP BY 1 HAVING count(DISTINCT source_product_ref)>1 ORDER BY 2 DESC LIMIT 10;
